import { useEffect } from 'react'
import { ArrowLeft } from 'lucide-react'
import { useCatalog } from '../lib/catalog-context'
import { SeriesCard } from '../components/SeriesCard'
import { navigate, useLink } from '../lib/router'
import { cx } from '../lib/utils'
import { setSeo, buildDirectoryMeta } from '../lib/seo'

/** 'a'…'z' + '0-9' for titles starting with anything else. */
const LETTERS = [...'abcdefghijklmnopqrstuvwxyz', '0-9']

const letterOf = (title: string): string => {
  const c = (title.trim()[0] ?? '').toLowerCase()
  return c >= 'a' && c <= 'z' ? c : '0-9'
}

/**
 * /directory — A–Z series directory. /directory/{letter} — one letter's
 * titles, alphabetical. The "manga directory" pattern every large reader
 * site exposes; also the hub that links author pages into the graph.
 */
export default function DirectoryPage({ letter }: { letter?: string }) {
  const { series: catalog, loading } = useCatalog()
  const link = useLink()
  const active = LETTERS.includes(letter ?? '') ? (letter as string) : undefined

  useEffect(() => {
    setSeo(buildDirectoryMeta(Boolean(active), active ?? null))
  }, [active])

  const counts = new Map<string, number>()
  for (const s of catalog) counts.set(letterOf(s.title), (counts.get(letterOf(s.title)) ?? 0) + 1)

  const list = active
    ? catalog
        .filter((s) => letterOf(s.title) === active)
        .sort((a, b) => a.title.localeCompare(b.title))
    : []

  return (
    <main className="animate-fade-up">
      <div
        className="border-b border-line"
        style={{ background: 'linear-gradient(115deg, hsl(20 30% 14%) 0%, hsl(30 28% 26%) 100%)' }}
      >
        <div className="mx-auto max-w-[1240px] px-4 py-12 text-paper sm:px-6 lg:px-8">
          <button
            onClick={() => navigate('/')}
            className="mb-6 inline-flex items-center gap-1.5 text-sm font-semibold text-white/70 transition-colors hover:text-white"
          >
            <ArrowLeft width={16} height={16} /> Home
          </button>
          <div className="eyebrow text-accent">Directory</div>
          <h1 className="mt-2 text-4xl font-extrabold tracking-tight sm:text-5xl">
            {active ? `Titles starting with “${active.toUpperCase()}”` : 'Manhwa & Manhua Directory'}
          </h1>
          <p className="mt-3 max-w-xl text-white/70">
            {active
              ? `${loading ? '…' : list.length} series, sorted alphabetically.`
              : 'Every series on MANHWAS, A to Z. Pick a letter to browse, or jump into the author directory.'}
          </p>
        </div>
      </div>

      <div className="mx-auto max-w-[1240px] px-4 py-8 sm:px-6 lg:px-8">
        {/* letter strip */}
        <div className="flex flex-wrap gap-2">
          {LETTERS.map((l) => (
            <a
              key={l}
              href={`/directory/${l}`}
              onClick={link(`/directory/${l}`)}
              className={cx(
                'h-10 min-w-10 rounded-full border px-3 text-center text-sm font-bold leading-10 transition-colors',
                l === active
                  ? 'border-accent bg-accent text-white'
                  : 'border-line-strong bg-paper text-ink-soft hover:border-ink hover:text-ink',
              )}
            >
              {l === '0-9' ? '0–9' : l.toUpperCase()}
              {counts.get(l) ? (
                <span className="ml-1.5 text-[11px] font-normal opacity-60">{counts.get(l)}</span>
              ) : null}
            </a>
          ))}
        </div>

        {active ? (
          <div className="mt-8 grid grid-cols-2 gap-x-5 gap-y-8 sm:grid-cols-3 lg:grid-cols-5">
            {list.map((s) => (
              <SeriesCard key={s.id} series={s} />
            ))}
            {!loading && list.length === 0 && (
              <p className="col-span-full py-10 text-center text-sm text-ink-faint">
                No titles start with “{active.toUpperCase()}” yet.
              </p>
            )}
          </div>
        ) : (
          <p className="mt-8 text-sm text-ink-soft">
            Looking for a specific creator?{' '}
            <a href="/genres" onClick={link("/genres")} className="font-semibold text-accent hover:underline">
              Browse by genre
            </a>{' '}
            or{' '}
            <a href="/catalog" onClick={link("/catalog")} className="font-semibold text-accent hover:underline">
              search the catalog
            </a>
            .
          </p>
        )}
      </div>
    </main>
  )
}
